<js>
result.toArray().slice(0,5).map(o=>{
    var detail = String(o.select('a:eq(0)').attr('href')).replace(/^\//, baseUrl.match(/(.+?\/\/[^\/]+\/)/)[1]);
    var J = org.jsoup.Jsoup.parse(java.ajax(detail));
    var oText = selector =>String(o.select(selector).text().trim()).replace(/.+：/, '');
    return {
       name:  oText('h3'),
       author: oText('.tags span:eq(0)'),
       tags:    [oText('.tags span:eq(2)'), oText('.tags span:eq(1)')].join(','),
       num:   oText('.tags span:eq(3)').replace('+',''),
       latest:  oText('p:eq(2) a')+ oText('.right span').replace(/(\d+-\d+).*/,'（$1）'),
       intro:  String(J.select('.intro').eq(0).text()).replace(/阅读(.*|\n)（.*）/,''),
       cover: o.select('img').attr('data-original'),
       catalogUrl: detail
    }
}).filter(v =>v.name);
</js>

